            return
        boundary.append(node.val)
        if node.left:
            self.leftBoundary(node.left, boundary)
        else:
            self.leftBoundary(node.right, boundary)

    def rightBoundary(self, node, boundary):
        if not node or not (node.left or node.right):
            return
        if node.right:
            self.rightBoundary(node.right, boundary)
        else:
            self.rightBoundary(node.left, boundary)
        boundary.append(node.val)

    def leaves(self, node, boundary):
        if not node:
            return
        if not (node.left or node.right):
            boundary.append(node.val)
        self.leaves(node.left, boundary)
        self.leaves(node.right, boundary)

    def boundaryOfBinaryTree(self, root):
        res = []
        if not root:
            return res
        res.append(root.val)
        self.leftBoundary(root.left, res)
        self.leaves(root, res)
        self.rightBoundary(root.right, res)
        return res
```


    The algorithm consists of two main parts: traversing the tree and appending the values to the boundary list. At a high level, the steps are as follows:

1. If the tree is empty, return an empty list.
2. Add the root value to the boundary list.
3. Traverse the left boundary, appending nodes' values as visited. This is done recursively, prioritizing the left child over the right child.
4. Traverse the tree and append the values of any leaves encountered.
5. Traverse the right boundary, appending nodes' values as visited. This is done backwards to account for the reverse order requirement of the right boundary.

The leftBoundary and rightBoundary functions are mostly the same, except the rightBoundary function adds values in reverse. The leaves function traverses the entire tree, adding values of any leaves encountered.

