        for i in range(left + 1, right + 1):
            if nums[i] > nums[maxIdx]:
                maxIdx = i

        root = TreeNode(nums[maxIdx])
        root.left = helper(nums, left, maxIdx - 1)
        root.right = helper(nums, maxIdx + 1, right)
        return root

    return helper(nums, 0, len(nums) - 1)
