def smallestSuperstring(words):
    def get_shared_length(a, b):
        for shared_length in range(min(len(a), len(b)), 0, -1):
            if a[-shared_length:] == b[:shared_length]:
                return shared_length
        return 0

    def merge(a, b, shared_length):
