    correct = 0
    mul = 1
    add = 0
    for i in range(len(s)):
        if s[i].isdigit():
            num = int(s[i])
            mul *= num
            if i == len(s) - 1 or s[i + 1] == '+':
                add += mul
                mul = 1
    correct = add

    wrongOrder = int(s[0])
    for i in range(2, len(s), 2):
        if s[i - 1] == '+':
            wrongOrder += int(s[i])
        else:
            wrongOrder *= int(s[i])

