def minWastedSpace(nums, k):
    n = len(nums)
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        total = 0
        for j in range(i, 0, -1):
            total += nums[j - 1]
            for l in range(k):
                dp[i][l + 1] = min(dp[i][l + 1], dp[j - 1][l] + (i - j + 1) * nums[j - 1] - total)

    return min(dp[n])
```


