        return sum
    max_sum = 0
    for i in range(1, num_slots + 1):
        if not used & (1 << (i - 1)):
            new_sum = sum + (nums[idx] & i)
            new_used = used | (1 << (i - 1))
            max_sum = max(max_sum, max_and_sum(nums, num_slots, idx + 1, new_used, new_sum))
            if idx + 1 < len(nums):
