def numBeautifulPartitions(s: str, k: int, minLength: int) -> int:
    MOD = 10**9 + 7
    primes = {'2', '3', '5', '7'}
    n = len(s)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
