def smallestWordForLCP(lcp):
    n = len(lcp)
    word = ['a'] * n
    for i in range(1, n):
        for j in range(1, n):
            if lcp[i][j] > min(lcp[i - 1][j], lcp[i][j - 1]):
                word[i + lcp[i][j] - 1] = max(word[i + lcp[i][j] - 1], chr(ord(word[i - 1]) + 1))
            elif lcp[i][j] < min(lcp[i - 1][j], lcp[i][j - 1]):
                return ""
    return "".join(word)
```

