from typing import List

class Task:
    def __init__(self, id: int, description: str, due_date: int, tags: List[str]):
        self.id = id
        self.description = description
        self.due_date = due_date
        self.tags = tags
        self.completed = False

class TodoList:

    def __init__(self):
        self.task_id = 1
        self.tasks = {}

    def addTask(self, userId: int, taskDescription: str, dueDate: int, tags: List[str]) -> int:
        if userId not in self.tasks:
            self.tasks[userId] = []
        self.tasks[userId].append(Task(self.task_id, taskDescription, dueDate, tags))
        self.task_id += 1
        return self.task_id - 1

    def getAllTasks(self, userId: int) -> List[str]:
        if userId not in self.tasks:
            return []
        user_tasks = sorted(self.tasks[userId], key=lambda task: task.due_date)
        res = [task.description for task in user_tasks if not task.completed]
        return res

    def getTasksForTag(self, userId: int, tag: str) -> List[str]:
        if userId not in self.tasks:
            return []
        user_tasks = sorted(self.tasks[userId], key=lambda task: task.due_date)
        res = [task.description for task in user_tasks if not task.completed and tag in task.tags]
        return res

    def completeTask(self, userId: int, taskId: int) -> None:
        if userId not in self.tasks:
            return
        for task in self.tasks[userId]:
            if task.id == taskId:
                task.completed = True
                break
```

    We define a `Task` class that keeps the task information such as `id`, `description`, `dueDate`, `tags`, and its completion status (`completed` field). 

The `TodoList` class contains a map, `tasks`, that stores the tasks of each user as a list. Then, we implement the methods `addTask`, `getAllTasks`, `getTasksForTag`, and `completeTask`, using the map and Task objects.

1. `addTask()` creates a new Task object with the provided `taskDescription`, `dueDate`, and `tags`, and then adds the task to the corresponding user's task list. It increments the `taskId` by 1.
2. `getAllTasks()` retrieves the user's task list, sorts the tasks by the due date, and creates a list of uncompleted task descriptions to return.
3. `getTasksForTag()` retrieves the user's task list, sorts the tasks by the due date, and creates a list of uncompleted task descriptions that have the specified tag.
4. `completeTask()` finds the task with the given task ID for the specified user and sets the `completed` field of the task to `true`.

